(() => {
  'use strict';
  const SAVE_KEY = 'eternal-realms-one-hero-v1';
  const regions = [
    {name:'Dämmerwald',chapter:'KAPITEL I',motto:'Ein uralter Wald erwacht zu neuem Leben.',scene:'DÄMMERWALD · LICHTUNG DER VERLORENEN',enemy:['Waldschrat','Mooskrabbler','Dämmerwolf','Dornenwicht'],boss:'Der Wurzelkönig'},
    {name:'Aschenöde',chapter:'KAPITEL II',motto:'Unter schwarzer Asche regt sich ein alter Fluch.',scene:'ASCHENÖDE · DIE GEBROCHENE WEITE',enemy:['Aschenpirscher','Glutkriecher','Knochenhund'],boss:'Varkhul, der Entflammte'},
    {name:'Frostmark',chapter:'KAPITEL III',motto:'Im ewigen Eis wartet die vergessene Krone.',scene:'FROSTMARK · GLETSCHERPASS',enemy:['Frostling','Eiswandler','Schneewolf'],boss:'Ylva, Königin des Reifs'},
    {name:'Smaragdküste',chapter:'KAPITEL IV',motto:'Die Flut singt von einem versunkenen Reich.',scene:'SMARAGDKÜSTE · GEZEITENRUINE',enemy:['Tiefenräuber','Korallenkrieger','Salzgeist'],boss:'Der Leviathan'},
    {name:'Schattenlande',chapter:'KAPITEL V',motto:'Jeder Schatten birgt eine verlorene Seele.',scene:'SCHATTENLANDE · NACHTFESTUNG',enemy:['Nachtwandler','Seelenzehrer','Dunkelritter'],boss:'Morthas, der Leere'},
    {name:'Himmelsgrat',chapter:'KAPITEL VI',motto:'Am Ende der Welt wartet das letzte Licht.',scene:'HIMMELSGRAT · HIMMELSTHRON',enemy:['Sternenwächter','Wolkenwyrm','Lichtloser'],boss:'Aurelion, der Ewige'}
  ];
  const slots = [{key:'weapon',name:'Waffe',icon:'⚔'},{key:'helm',name:'Helm',icon:'♜'},{key:'armor',name:'Rüstung',icon:'◈'},{key:'gloves',name:'Handschuhe',icon:'♧'},{key:'boots',name:'Stiefel',icon:'⌑'},{key:'ring',name:'Ring',icon:'○'},{key:'amulet',name:'Amulett',icon:'◇'}];
  const rarities = [{name:'Gewöhnlich',color:'#9b9ba0',mult:1},{name:'Ungewöhnlich',color:'#65b778',mult:1.35},{name:'Selten',color:'#5796df',mult:1.8},{name:'Episch',color:'#a875db',mult:2.5},{name:'Legendär',color:'#e4a344',mult:3.6},{name:'Mythisch',color:'#e16c60',mult:5.2},{name:'Göttlich',color:'#e9d47c',mult:8}];
  const upgrades = [{id:'blade',name:'Klingenkunst',icon:'⚔',desc:'Klickschaden +2',base:12},{id:'focus',name:'Fokus',icon:'✧',desc:'Autom. Schaden +1/s',base:20},{id:'fortune',name:'Goldrausch',icon:'◈',desc:'Goldfund +10%',base:35}];
  const fresh = () => ({gold:0,shards:0,level:1,xp:0,stage:1,kills:0,totalKills:0,damage:1,auto:true,upgrades:{blade:0,focus:0,fortune:0},attributes:{str:5,vit:5,dex:5,int:5,luk:5},gear:{},bosses:0,skillReady:0,quests:{kills:0,bosses:0,upgrades:0,claimDay:''},lastSeen:Date.now(),unlocked:1});
  let state = fresh();
  try { const saved = JSON.parse(localStorage.getItem(SAVE_KEY)||'null'); if(saved && saved.level) state={...fresh(),...saved,attributes:{...fresh().attributes,...saved.attributes},upgrades:{...fresh().upgrades,...saved.upgrades},gear:saved.gear||{},quests:{...fresh().quests,...saved.quests}}; } catch(e) { console.warn('Save could not be loaded',e); }
  let enemyHp=0, enemyMax=0, combatTime=Date.now(), toastTimer;
  const $ = id => document.getElementById(id);
  const fmt = n => { if(!Number.isFinite(n)) return '∞'; if(n<1000) return Math.floor(n).toLocaleString('de-DE'); const units=['','Tsd.','Mio.','Mrd.','Bio.','B']; let i=-1; while(n>=1000&&i<units.length-2){n/=1000;i++} return (n>=100?Math.floor(n):n>=10?n.toFixed(1):n.toFixed(2)).replace('.',',')+' '+units[i+1]; };
  const regionIndex = () => Math.min(5,Math.floor((state.stage-1)/5));
  const isBoss = () => state.stage%5===0 && state.kills===0;
  const enemyLevel = () => Math.max(1,Math.floor((state.stage-1)*1.8+1));
  const attrPower = () => state.attributes.str*.65+state.attributes.dex*.12+state.attributes.int*.18;
  const equipmentPower = () => Object.values(state.gear).reduce((a,g)=>a+(g?.power||0),0);
  const clickDamage = () => Math.max(1,(state.damage+state.upgrades.blade*2+attrPower()+equipmentPower())*(1+state.upgrades.focus*.025));
  const autoDps = () => (1+state.upgrades.focus+state.level*.15+equipmentPower()*.3+state.attributes.int*.1)* (1+state.upgrades.blade*.04);
  const critChance=()=>Math.min(65,5+state.attributes.dex*.22+state.attributes.luk*.18);
  const goldMultiplier=()=>1+state.upgrades.fortune*.1+state.attributes.luk*.015+Object.values(state.gear).reduce((a,g)=>a+(g?.gold||0),0);
  function save(){state.lastSeen=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch(e){}}
  function toast(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
  function enemyBase(){return Math.floor(12*Math.pow(1.43,Math.max(0,state.stage-1))*(isBoss()?10:1));}
  function setupEnemy(){enemyMax=enemyBase();enemyHp=enemyMax;const r=regions[regionIndex()];$('enemy-name').textContent=isBoss()?r.boss:r.enemy[(state.stage+state.kills)%r.enemy.length];$('enemy-level').textContent=`STUFE ${fmt(enemyLevel())}${isBoss()?' · BOSS':''}`;$('scene-location').textContent=r.scene;$('realm-name').textContent=r.name;$('boss-banner').classList.toggle('show',isBoss());document.querySelector('.enemy-wrap').classList.toggle('boss-enemy',isBoss());updateEnemyBar();}
  function updateEnemyBar(){let existing=document.querySelector('.enemy-hp');if(!existing){existing=document.createElement('div');existing.className='enemy-hp';existing.innerHTML='<div class="enemy-hp-label"></div><div class="enemy-hp-track"><i></i></div>';document.querySelector('.enemy-wrap').prepend(existing)}const pct=Math.max(0,enemyHp/enemyMax*100);existing.querySelector('i').style.width=pct+'%';existing.querySelector('.enemy-hp-label').textContent=`${fmt(enemyHp)} / ${fmt(enemyMax)}`;}
  function floatDamage(amount,crit=false){const layer=$('hit-layer'),el=document.createElement('div');el.className='damage-number'+(crit?' crit':'');el.textContent=(crit?'KRITISCH! ':'')+fmt(amount);el.style.left=(62+Math.random()*9)+'%';el.style.top=(35+Math.random()*16)+'%';layer.appendChild(el);setTimeout(()=>el.remove(),850)}
  function damage(amount,source='click'){if(enemyHp<=0)return;let crit=Math.random()*100<critChance();if(crit)amount*=2.2;enemyHp=Math.max(0,enemyHp-amount);updateEnemyBar();floatDamage(amount,crit);const ew=document.querySelector('.enemy-wrap');ew.classList.remove('hit');void ew.offsetWidth;ew.classList.add('hit');if(source==='click'){$('hero-click').classList.remove('attack');void $('hero-click').offsetWidth;$('hero-click').classList.add('attack')}if(enemyHp<=0)defeatEnemy();}
  function gainXp(amount){state.xp+=amount;while(state.xp>=xpNeed()){state.xp-=xpNeed();state.level++;state.attributes.str++;state.attributes.vit++;state.attributes.dex++;state.attributes.int++;state.attributes.luk++;toast(`Stufe ${state.level} erreicht! Alle Attribute +1`)} }
  function xpNeed(){return Math.floor(100*Math.pow(state.level,1.35))}
  function defeatEnemy(){const boss=isBoss(),r=regions[regionIndex()];const gold=Math.floor((5+state.stage*2+enemyLevel())*goldMultiplier()*(boss?8:1));state.gold+=gold;state.totalKills++;state.kills++;state.quests.kills++;gainXp(Math.floor((12+state.stage*3)*(boss?7:1)));const scene=$('hit-layer');const loot=document.createElement('div');loot.className='loot-pop';loot.textContent=`+${fmt(gold)} ◈`;loot.style.left=(53+Math.random()*15)+'%';loot.style.top='53%';scene.appendChild(loot);setTimeout(()=>loot.remove(),1450);
    if(boss){state.bosses++;state.quests.bosses++;state.shards+=1+Math.floor(Math.random()*2);dropGear();toast(`${r.boss} besiegt! Seltene Beute gefunden.`)}
    if(state.kills>=10){state.stage++;state.kills=0;if(regionIndex()+1>state.unlocked)state.unlocked=regionIndex()+1;if(state.stage===25)toast('Das Vermächtnis wartet. Wiedergeburt freigeschaltet!')}
    setupEnemy();render();if(state.totalKills%5===0)save();
  }
  function dropGear(){const roll=Math.random(),rarity=roll>.997?6:roll>.97?5:roll>.88?4:roll>.68?3:roll>.42?2:roll>.17?1:0;const slot=slots[Math.floor(Math.random()*slots.length)],base=4+state.stage*1.6;const item={name:`${['Schlichte','Wilde','Runen','Dämmer','Königs','Sternen','Göttliche'][rarity]} ${slot.name}`,rarity,power:Math.floor(base*rarities[rarity].mult),gold:rarity>=3?.03:0};const old=state.gear[slot.key];if(!old||item.power>old.power){state.gear[slot.key]=item;toast(`${rarities[rarity].name}: ${item.name} ausgerüstet!`)}else toast(`${rarities[rarity].name} ${slot.name} erhalten – nicht stärker als deine Ausrüstung.`)}
  function buyUpgrade(id){const u=upgrades.find(x=>x.id===id),lv=state.upgrades[id],cost=Math.floor(u.base*Math.pow(1.75,lv));if(state.gold<cost){toast('Nicht genug Gold. Besiege Gegner für mehr!');return}state.gold-=cost;state.upgrades[id]++;state.quests.upgrades++;render();toast(`${u.name} verbessert!`);save()}
  function castSkill(){const now=Date.now();if(now<state.skillReady){toast('Arkaner Schlag lädt noch auf.');return}state.skillReady=now+12000;const hit=clickDamage()*8;damage(hit,'skill');$('skill-cast').classList.add('casting');setTimeout(()=>$('skill-cast').classList.remove('casting'),350);toast(`Arkaner Schlag verursacht ${fmt(hit)} Schaden!`);save()}
  function equipSlot(slotKey){const item=state.gear[slotKey];if(item){openModal(`<h2>${item.name}</h2><p style="color:${rarities[item.rarity].color}">${rarities[item.rarity].name} · ${slots.find(s=>s.key===slotKey).name}</p><p>Erhöht deine Kampfkraft um <b>${fmt(item.power)}</b>${item.gold?` und Goldfund um ${Math.round(item.gold*100)}%`:''}.</p><button class="modal-action" data-action="close-modal">SCHLIESSEN</button>`)}else toast(`Noch keine ${slots.find(s=>s.key===slotKey).name} gefunden. Besiege Bosse!`)}
  function renderGear(){ $('gear-row').innerHTML=slots.map(s=>{const g=state.gear[s.key];return `<button class="gear-slot ${g?'has-item':''}" data-slot="${s.key}" title="${g?g.name:s.name+' (leer)'}"><span class="gear-icon" ${g?`style="color:${rarities[g.rarity].color}"`:''}>${s.icon}</span>${g?`<span class="gear-rarity">✦</span>`:''}<small>${s.name.toUpperCase()}</small></button>`}).join('');document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>equipSlot(b.dataset.slot));}
  function renderUpgrades(){ $('upgrade-cards').innerHTML=upgrades.map(u=>{const lv=state.upgrades[u.id],cost=Math.floor(u.base*Math.pow(1.75,lv));return `<button class="upgrade-card" data-upgrade="${u.id}" ${state.gold<cost?'disabled':''}><span class="owned">Lv. ${lv}</span><div class="upgrade-card-top"><span class="upgrade-card-icon">${u.icon}</span><b>${u.name}</b></div><small>${u.desc}</small><strong>◈ ${fmt(cost)}</strong></button>`}).join('');document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>buyUpgrade(b.dataset.upgrade));}
  function render(){const r=regions[regionIndex()];$('realm-name').textContent=r.name;$('gold-top').textContent=fmt(state.gold);$('shards-top').textContent=fmt(state.shards);$('hero-level').textContent=fmt(state.level);$('xp-label').textContent=`${fmt(state.xp)} / ${fmt(xpNeed())}`;$('xp-progress').style.width=Math.min(100,state.xp/xpNeed()*100)+'%';$('xp-percent').textContent=Math.floor(state.xp/xpNeed()*100)+'%';$('next-level').textContent=state.level+1;$('stage-number').textContent=String(state.stage).padStart(2,'0');$('stage-kills').textContent=`${state.kills} / 10 Gegner`;$('stage-progress').style.width=(state.kills*10)+'%';$('dps-value').textContent=fmt(autoDps());$('crit-value').textContent=Math.floor(critChance())+'%';$('gold-bonus').textContent='+'+Math.floor((goldMultiplier()-1)*100)+'%';$('power-value').textContent=fmt(clickDamage()+autoDps()*2);$('str-value').textContent=fmt(state.attributes.str);$('vit-value').textContent=fmt(state.attributes.vit);$('dex-value').textContent=fmt(state.attributes.dex);$('int-value').textContent=fmt(state.attributes.int);$('luk-value').textContent=fmt(state.attributes.luk);$('auto-toggle').classList.toggle('off',!state.auto);$('auto-toggle').querySelector('b').textContent=state.auto?'AN':'AUS';$('chapter-label')?.replaceChildren(document.createTextNode(r.chapter));renderGear();renderUpgrades();updateEnemyBar();}
  function openModal(html){$('modal-content').innerHTML=html;$('modal').classList.remove('hidden')}
  function closeModal(){$('modal').classList.add('hidden')}
  const pageInfo={realms:['Die sechs Königreiche','Sechs Reiche. Unzählige Prüfungen. Jedes birgt neue Gegner und größere Schätze.'],dungeons:['Dungeons','Stelle dich besonderen Prüfungen und verdiene Gold, Erfahrung und seltene Beute.'],tower:['Endloser Turm','Etage um Etage. Wie weit trägt dich deine Legende?'],character:['Dein Charakter','Ein Held. Eine Legende. Für immer.'],skills:['Fähigkeiten & Talente','Meistere uralte Kräfte und forme deinen eigenen Kampfstil.'],equipment:['Ausrüstung','Sieben Plätze. Unendliche Möglichkeiten. Jedes Stück macht dich stärker.'],quests:['Tägliche Quests','Kleine Taten. Große Belohnungen. Erneuert sich jeden Tag.']};
  function showTab(tab){if(tab==='battle'){ $('battle-view').classList.remove('hidden');$('subpage').classList.add('hidden');document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.tab==='battle'));return}if(!pageInfo[tab])return;const [title,subtitle]=pageInfo[tab];$('battle-view').classList.add('hidden');$('subpage').classList.remove('hidden');$('subpage-title').textContent=title;$('subpage-subtitle').textContent=subtitle;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.tab===tab));$('subpage-content').innerHTML=pageMarkup(tab);bindPage(tab);}
  function pageMarkup(tab){
    if(tab==='realms')return `<div class="page-grid">${regions.map((r,i)=>`<article class="content-card"><div style="font-size:9px;color:#b59b64;letter-spacing:1px;margin-bottom:8px">KAPITEL 0${i+1}</div><h3>${r.name}</h3><p>${r.motto}<br>Boss: ${r.boss}</p><button data-realm="${i}" ${i>state.unlocked?'disabled':''}>${i<state.unlocked?'REICH BETRETEN':'GESPERRT'}</button></article>`).join('')}</div>`;
    if(tab==='dungeons')return `<div class="page-grid">${[['Goldmine','Gold verdienen. Besiege in 60 Sekunden so viele Gegner wie möglich.','◈'],['Erfahrungsriss','Ein Riss voller verlorener Erinnerungen. Doppelte Erfahrung für 90 Sekunden.','✧'],['Boss-Rush','Drei Bosse in Folge. Seltene Ausrüstung und Seelensplitter.','⚔']].map((x,i)=>`<article class="content-card"><div style="color:#c3a45f;font-size:20px;margin-bottom:8px">${x[2]}</div><h3>${x[0]}</h3><p>${x[1]}</p><button data-dungeon="${i}">DUNGEON STARTEN</button></article>`).join('')}</div>`;
    if(tab==='tower')return `<article class="content-card" style="max-width:560px;text-align:center;padding:35px"><div style="font-size:32px;color:#c5a664">♜</div><h3>Der Endlose Turm</h3><p>Deine bisher höchste Etage: <b>${Math.max(1,state.stage-1)}</b><br>Stelle dich einem Wächter und verdiene Seelensplitter.</p><button data-tower>ETAGE ${Math.max(1,state.stage)} BETRETEN</button></article>`;
    if(tab==='character')return `<div class="content-card"><h3>Attribute & Vermächtnis</h3><p>Jeder Stufenaufstieg stärkt alle Attribute. Deine Ausrüstung ergänzt deine Kampfkraft.</p><div class="stat-list">${[['Stufe',state.level],['Kampfkraft',fmt(clickDamage()+autoDps()*2)],['Schaden pro Sekunde',fmt(autoDps())],['Kritische Treffer',Math.floor(critChance())+'%'],['Besiegte Gegner',fmt(state.totalKills)],['Besiegte Bosse',fmt(state.bosses)]].map(x=>`<div class="stat-box"><small>${x[0].toUpperCase()}</small><b>${x[1]}</b></div>`).join('')}</div></div><article class="content-card" style="margin-top:12px"><h3>Wiedergeburt · Das Vermächtnis</h3><p>Setze deine Reise zurück und erhalte permanente Seelensplitter. Wird auf Gebiet 25 freigeschaltet.</p><button data-prestige ${state.stage<25?'disabled':''}>${state.stage<25?'GEBIET 25 ERFORDERLICH':'WIEDERGEBOREN WERDEN'}</button></article>`;
    if(tab==='skills')return `<div class="page-grid"><article class="content-card"><div style="color:#d8b46b;font-size:22px">ϟ</div><h3>Arkaner Schlag</h3><p>Entfessle einen mächtigen Schlag für das Achtfache deines Schadens. Abklingzeit: 12 Sekunden.</p><button data-cast>FÄHIGKEIT EINSETZEN · Q</button></article><article class="content-card"><div style="color:#d8b46b;font-size:22px">✧</div><h3>Talentbaum</h3><p>Dein wachsendes Vermächtnis stärkt Stärke, Vitalität, Geschick, Intelligenz und Glück.</p><button data-talent>STUFENAUFSTIEG-DETAILS</button></article></div>`;
    if(tab==='equipment')return `<div class="page-grid">${slots.map(s=>{const g=state.gear[s.key];return `<article class="content-card"><div style="font-size:21px;color:${g?rarities[g.rarity].color:'#797a82'};margin-bottom:6px">${s.icon}</div><h3>${s.name}</h3><p>${g?`<span style="color:${rarities[g.rarity].color}">${g.name}</span><br>${rarities[g.rarity].name} · +${fmt(g.power)} Kampfkraft`:'Noch nicht gefunden. Besiege Bosse, um Beute zu erhalten.'}</p><button data-slot-page="${s.key}">${g?'DETAILS':'LEER'}</button></article>`}).join('')}</div>`;
    if(tab==='quests'){const day=new Date().toISOString().slice(0,10),claimed=state.quests.claimDay===day;return `<div class="page-grid"><article class="content-card"><h3>Waldläufer</h3><p>Besiege 25 Gegner. <b>${Math.min(25,state.quests.kills)} / 25</b></p><div class="xp-track"><i style="width:${Math.min(100,state.quests.kills/25*100)}%"></i></div><button data-quest="kills" ${state.quests.kills<25?'disabled':''}>${state.quests.kills>=25?'BELOHNUNG · 150 GOLD':'IN ARBEIT'}</button></article><article class="content-card"><h3>Jäger der Alten</h3><p>Besiege 2 Bosse. <b>${Math.min(2,state.quests.bosses)} / 2</b></p><div class="xp-track"><i style="width:${Math.min(100,state.quests.bosses/2*100)}%"></i></div><button data-quest="bosses" ${state.quests.bosses<2?'disabled':''}>${state.quests.bosses>=2?'BELOHNUNG · 2 SPLITTER':'IN ARBEIT'}</button></article><article class="content-card"><h3>Täglicher Segen</h3><p>Deine tägliche Belohnung wartet. Erneuert sich einmal pro Tag.</p><button data-daily ${claimed?'disabled':''}>${claimed?'HEUTE ABGEHOLT':'BELOHNUNG ABHOLEN · 100 GOLD'}</button></article><article class="content-card"><h3>Offline-Fortschritt</h3><p>Während deiner Abwesenheit sammelt dein Held Gold und Erfahrung.</p><button data-offline>OFFLINE-ERTRAG ANSEHEN</button></article></div>`;}
    return '';
  }
  function bindPage(tab){document.querySelectorAll('[data-realm]').forEach(b=>b.onclick=()=>{const i=+b.dataset.realm;if(i>state.unlocked){toast('Dieses Königreich ist noch nicht erreichbar.');return}state.stage=Math.max(state.stage,i*5+1);state.kills=0;setupEnemy();showTab('battle');render();toast(`${regions[i].name} betreten.`);save()});document.querySelectorAll('[data-dungeon]').forEach(b=>b.onclick=()=>{const i=+b.dataset.dungeon;if(i===0){const reward=Math.floor(100+state.stage*25);state.gold+=reward;render();toast(`Goldmine abgeschlossen: +${fmt(reward)} Gold`)}else if(i===1){const reward=Math.floor(80+state.stage*14);gainXp(reward);render();toast(`Erfahrungsriss abgeschlossen: +${fmt(reward)} EP`)}else{if(state.bosses<3){toast('Besiege zuerst einen Boss im Abenteuer.');return}state.bosses-=3;state.shards+=5;dropGear();render();toast('Boss-Rush abgeschlossen! +5 Seelensplitter.')}save()});document.querySelector('[data-tower]')?.addEventListener('click',()=>{state.shards+=1+Math.floor(state.stage/5);state.gold+=Math.floor(state.stage*25);state.stage++;state.kills=0;setupEnemy();render();toast('Turmwächter besiegt! Du steigst eine Etage auf.');save()});document.querySelector('[data-cast]')?.addEventListener('click',castSkill);document.querySelector('[data-talent]')?.addEventListener('click',()=>openModal('<h2>Talentbaum</h2><p>Mit jedem Level erhältst du +1 auf alle fünf Attribute. Stärke erhöht den Klickschaden, Intelligenz deine automatischen Angriffe, Geschick und Glück steigern deine kritischen Treffer.</p><button class="modal-action" data-action="close-modal">VERSTANDEN</button>'));document.querySelectorAll('[data-slot-page]').forEach(b=>b.onclick=()=>equipSlot(b.dataset.slotPage));document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>{const q=b.dataset.quest;if(q==='kills'&&state.quests.kills>=25){state.quests.kills-=25;state.gold+=150}else if(q==='bosses'&&state.quests.bosses>=2){state.quests.bosses-=2;state.shards+=2}else return;render();showTab('quests');toast('Questbelohnung erhalten!');save()});document.querySelector('[data-daily]')?.addEventListener('click',()=>{const day=new Date().toISOString().slice(0,10);if(state.quests.claimDay===day)return;state.quests.claimDay=day;state.gold+=100;render();showTab('quests');toast('Täglicher Segen: +100 Gold!');save()});document.querySelector('[data-offline]')?.addEventListener('click',()=>showOfflineModal(0));document.querySelector('[data-prestige]')?.addEventListener('click',prestige);}
  function prestige(){if(state.stage<25)return;openModal(`<h2>Wiedergeburt</h2><p>Dein Vermächtnis wird stärker. Du erhältst <b>${Math.floor(state.stage/5)} Seelensplitter</b>. Stufe, Gold, Gebiet und Ausrüstung werden zurückgesetzt.</p><button class="modal-action" data-action="confirm-prestige">WIEDERGEBOREN WERDEN</button>`)}
